package status

import (
	"crypto/tls"
	"crypto/x509"
	"net"
	"strings"
	"time"
)

// hostWithPort defaults a bare target to :443, the assumption SSLChecker and
// the certificate viewer both make about an unqualified target.
func hostWithPort(target string) string {
	if strings.Contains(target, ":") {
		return target
	}
	return target + ":443"
}

// FetchCertificateChain dials target and returns the certificate chain the
// server presented, leaf first — possibly empty, which the caller (not this
// function) is left to judge: SSLChecker and the certificate viewer report an
// empty chain differently. It is the dial SSLChecker.Check already pays on
// every refresh, pulled out so the document viewer can ask the same question
// again without a second copy of the dial.
func FetchCertificateChain(target string, timeout time.Duration) ([]*x509.Certificate, error) {
	dialer := &net.Dialer{Timeout: timeout}
	conn, err := tls.DialWithDialer(dialer, "tcp", hostWithPort(target), &tls.Config{
		InsecureSkipVerify: false, // Validate certificates
	})
	if err != nil {
		return nil, err
	}
	defer func() { _ = conn.Close() }()

	return conn.ConnectionState().PeerCertificates, nil
}
package status

import (
	"context"
	"fmt"
	"time"

	"github.com/anthnel/devdesk/internal/config"
)

// SSLChecker checks SSL/TLS certificates
type SSLChecker struct {
	timeout time.Duration
}

// NewSSLChecker creates a new SSLChecker
func NewSSLChecker(timeout time.Duration) *SSLChecker {
	return &SSLChecker{
		timeout: timeout,
	}
}

// Check checks a host's SSL certificate
func (s *SSLChecker) Check(ctx context.Context, component config.ComponentConfig) ComponentStatus {
	result := ComponentStatus{
		Name:      component.Name,
		Type:      TypeSSL,
		Target:    component.Target,
		Timestamp: time.Now(),
	}

	if component.Target == "" {
		result.Status = StatusError
		result.Error = "target not configured"
		return result
	}

	// Measure connection time
	start := time.Now()
	certs, err := FetchCertificateChain(component.Target, s.timeout)
	result.ResponseTime = time.Since(start)

	if err != nil {
		result.Status = StatusDown
		result.Error = err.Error()
		return result
	}
	if len(certs) == 0 {
		result.Status = StatusError
		result.Error = "no certificates found"
		return result
	}

	// Use leaf certificate (first in chain)
	cert := certs[0]

	// Extract certificate data
	notAfter := cert.NotAfter
	issuer := cert.Issuer.CommonName
	if issuer == "" {
		// Fallback to Organization if CommonName is empty
		if len(cert.Issuer.Organization) > 0 {
			issuer = cert.Issuer.Organization[0]
		} else {
			issuer = "Unknown"
		}
	}
	daysLeft := int(time.Until(notAfter).Hours() / 24)

	// Populate SSL-specific fields
	result.SSLExpires = &notAfter
	result.SSLDaysLeft = &daysLeft
	result.SSLIssuer = issuer

	// Determine status based on days left
	if daysLeft < 0 {
		result.Status = StatusError
		result.Error = "certificate expired"
	} else if daysLeft < 7 {
		result.Status = StatusError
		result.Error = fmt.Sprintf("expires in %d days", daysLeft)
	} else if daysLeft <= CertRenewWindowDays {
		result.Status = StatusWarning
		result.Error = fmt.Sprintf("expires in %d days", daysLeft)
	} else {
		result.Status = StatusOK
	}

	return result
}
package status

import "time"

// ComponentType represents the check type
type ComponentType string

const (
	TypeHTTP  ComponentType = "http"
	TypeHTTPS ComponentType = "https"
	TypeICMP  ComponentType = "icmp"
	TypeDNS   ComponentType = "dns"
	TypeSSL   ComponentType = "ssl"
)

// StatusType represents the possible states
type StatusType string

const (
	StatusOK      StatusType = "OK"
	StatusDown    StatusType = "DOWN"
	StatusError   StatusType = "ERROR"
	StatusWarning StatusType = "WARNING"
)

// ComponentStatus represents a component's state
type ComponentStatus struct {
	Name         string
	Type         ComponentType
	Target       string
	Status       StatusType
	ResponseTime time.Duration
	Error        string
	Timestamp    time.Time

	// SSL-specific fields (optional, only populated for SSL type)
	SSLDaysLeft *int       // Pointer to allow nil for non-SSL types
	SSLExpires  *time.Time // Certificate expiration date
	SSLIssuer   string     // Issuer CommonName
}

// String returns a textual representation of the status
func (s StatusType) String() string {
	return string(s)
}
package status

// CertState is what a monitored certificate is, as opposed to what a service
// is. A service is reachable or it is not; a certificate has a date, so it
// has one more state — the one where it is still valid and already demands
// action.
//
// That is why certificates cannot borrow the monitors' vocabulary.
// `up` / `down` / `error` lumped together three facts that are not handled
// the same way: an expired certificate (the service is already broken), a
// certificate due for renewal (it is not broken yet, and this is the only
// moment where action can be taken), and a certificate that could not be
// read (nothing is known). The third is the only one that is truly an
// error.
type CertState string

const (
	// CertValid — read, and far from its expiry.
	CertValid CertState = "valid"
	// CertToRenew — read, still valid, and inside the renewal window.
	CertToRenew CertState = "to renew"
	// CertExpired — read, and its date has passed.
	CertExpired CertState = "expired"
	// CertError — not read at all: unreachable host, refused handshake,
	// empty chain, target not configured. This is an absence of a
	// measurement, not a verdict on the certificate.
	CertError CertState = "error"
)

// CertRenewWindowDays is where a certificate stops being a date and becomes a
// task. It matches SSLChecker's `WARNING` window: the two answer the same
// question, and two diverging thresholds would make the dashboard say
// `to renew` about something `:status` still shows in green.
const CertRenewWindowDays = 30

// CertStateOf classifies one monitored certificate.
//
// It is decided from `SSLDaysLeft` and not from `Status`, because
// `StatusType` does not have four values to give: SSLChecker returns
// `ERROR` both for an expired certificate and for one expiring in six days,
// and `DOWN` for an unreachable host. The number of days, on the other
// hand, distinguishes the three — and its absence is exactly the case where
// nothing could be read.
func CertStateOf(c ComponentStatus) CertState {
	if c.SSLDaysLeft == nil {
		return CertError
	}
	switch days := *c.SSLDaysLeft; {
	case days < 0:
		return CertExpired
	case days <= CertRenewWindowDays:
		return CertToRenew
	default:
		return CertValid
	}
}

// CertCounts tallies a set of monitored certificates, one figure per state.
func CertCounts(certs []ComponentStatus) (valid, toRenew, expired, errored int) {
	for _, c := range certs {
		switch CertStateOf(c) {
		case CertValid:
			valid++
		case CertToRenew:
			toRenew++
		case CertExpired:
			expired++
		case CertError:
			errored++
		}
	}
	return
}

// Package netproxy decides which proxy a connection to a host travels through,
// the way an https request to that host would (DEVDESK-581), so that code which
// opens its own connections follows the same path as net/http.
package netproxy

import (
	"net/http"
	"net/url"
)

// Selector says which proxy carries a connection to u; nil, nil means direct.
// A nil Selector behaves like FromEnvironment.
//
// An error a Selector returns ends up in the text of a *Error (StepSelect) shown
// to the user, so it must never contain the raw proxy URL, which may carry
// credentials: describe the problem without echoing the value.
type Selector func(u *url.URL) (*url.URL, error)

// FromEnvironment is http.ProxyFromEnvironment(&http.Request{URL: u}): the same
// function and the same once-per-process cache as the HTTPS monitor.
func FromEnvironment(u *url.URL) (*url.URL, error) {
	return http.ProxyFromEnvironment(&http.Request{URL: u})
}

// ForRequest adapts s to http.Transport.Proxy. A nil s falls back to
// FromEnvironment, so the zero value follows the proxy environment variables.
func (s Selector) ForRequest(r *http.Request) (*url.URL, error) {
	if s == nil {
		return FromEnvironment(r.URL)
	}
	return s(r.URL)
}

// NewTransport returns http.DefaultTransport.Clone() with Proxy = s.ForRequest,
// so timeouts and limits match the default transport. A nil s is equivalent to
// FromEnvironment.
func NewTransport(s Selector) *http.Transport {
	t := http.DefaultTransport.(*http.Transport).Clone()
	t.Proxy = s.ForRequest
	return t
}
// Package connectproxy is an HTTP CONNECT proxy for tests (DEVDESK-581). It
// answers CONNECT the way a corporate proxy does, can redirect a target to a
// real test server, refuse, or stay silent, and records what it was asked.
//
// It imports testing and is meant to be imported from _test.go files only, so
// it never reaches the production binary.
//
// The proxy owns its listener from the start (httptest binds 127.0.0.1:0 and
// keeps the socket open until the test ends), so it never hands a "free" port
// to code that binds it later (DEVDESK-35).
package connectproxy

import (
	"crypto/x509"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sync"
	"testing"
	"time"
)

// Options shapes how the proxy answers a CONNECT. The zero value tunnels to
// the requested target as is.
type Options struct {
	// Route maps the CONNECT target ("example.com:443") to the address the
	// proxy really dials. Nil dials the target itself.
	Route func(target string) string
	// Refuse, when non-zero, answers every CONNECT with this status code. It
	// takes precedence over Silent.
	Refuse int
	// Silent accepts the connection and never answers. Ignored when Refuse is set.
	Silent bool
	// TLS serves the proxy itself over TLS, to be used as an https:// proxy.
	TLS bool
}

// Request is what the proxy saw in one CONNECT.
type Request struct {
	// Target is the authority of the CONNECT line, "host:port".
	Target string
	// ProxyAuthorization is the Proxy-Authorization header, empty when absent.
	ProxyAuthorization string
}

// Proxy is a running test proxy. Start returns one; it stops on t.Cleanup.
type Proxy struct {
	srv  *httptest.Server
	opts Options

	mu    sync.Mutex
	reqs  []Request
	conns []net.Conn
	done  bool
}

// Start launches a proxy on 127.0.0.1 and stops it when the test ends.
func Start(t testing.TB, opts Options) *Proxy {
	t.Helper()
	p := &Proxy{opts: opts}
	p.srv = httptest.NewUnstartedServer(http.HandlerFunc(p.serve))
	if opts.TLS {
		p.srv.StartTLS()
	} else {
		p.srv.Start()
	}
	t.Cleanup(p.stop)
	return p
}

// URL is the proxy address to hand to the code under test: http:// or, with
// Options.TLS, https://. Each call returns a fresh copy the caller may edit,
// for instance to add a userinfo.
func (p *Proxy) URL() *url.URL {
	u, err := url.Parse(p.srv.URL)
	if err != nil {
		panic("connectproxy: unparsable listener URL: " + err.Error())
	}
	return u
}

// RootCAs is a pool that trusts the proxy's own certificate; it is only
// meaningful with Options.TLS.
func (p *Proxy) RootCAs() *x509.CertPool {
	pool := x509.NewCertPool()
	pool.AddCert(p.srv.Certificate())
	return pool
}

// Requests returns the CONNECTs received so far, oldest first.
func (p *Proxy) Requests() []Request {
	p.mu.Lock()
	defer p.mu.Unlock()
	return append([]Request(nil), p.reqs...)
}

func (p *Proxy) serve(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodConnect {
		http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
		return
	}
	target := r.Host
	p.mu.Lock()
	p.reqs = append(p.reqs, Request{Target: target, ProxyAuthorization: r.Header.Get("Proxy-Authorization")})
	p.mu.Unlock()

	if p.opts.Refuse != 0 {
		http.Error(w, http.StatusText(p.opts.Refuse), p.opts.Refuse)
		return
	}
	if p.opts.Silent {
		if conn, _, err := http.NewResponseController(w).Hijack(); err == nil {
			p.hold(conn)
		}
		return
	}

	addr := target
	if p.opts.Route != nil {
		addr = p.opts.Route(target)
	}
	upstream, err := net.DialTimeout("tcp", addr, 5*time.Second)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusBadGateway), http.StatusBadGateway)
		return
	}
	client, rw, err := http.NewResponseController(w).Hijack()
	if err != nil {
		_ = upstream.Close()
		return
	}
	if !p.hold(client) || !p.hold(upstream) {
		return
	}
	if _, err := io.WriteString(client, "HTTP/1.1 200 Connection Established\r\n\r\n"); err != nil {
		return
	}
	// Bytes the client sent right behind the CONNECT sit in rw's reader.
	var pipes sync.WaitGroup
	pipes.Add(2)
	go func() {
		defer pipes.Done()
		_, _ = io.Copy(upstream, rw.Reader)
		_ = upstream.Close()
	}()
	go func() {
		defer pipes.Done()
		_, _ = io.Copy(client, upstream)
		_ = client.Close()
	}()
	pipes.Wait()
}

// hold remembers conn so stop can close it, since a hijacked connection is no
// longer tracked by the HTTP server. It closes conn and reports false when the
// proxy is already stopped.
func (p *Proxy) hold(conn net.Conn) bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.done {
		_ = conn.Close()
		return false
	}
	p.conns = append(p.conns, conn)
	return true
}

func (p *Proxy) stop() {
	p.mu.Lock()
	p.done = true
	conns := p.conns
	p.conns = nil
	p.mu.Unlock()
	for _, c := range conns {
		_ = c.Close()
	}
	p.srv.Close()
}
